// ---------------------------------------------------------------------------
// Content policy
// ---------------------------------------------------------------------------

/// Strip control characters and collapse pathological whitespace.
///
/// Terminal titles and agent labels are attacker-adjacent input: they can
/// carry escape sequences, newlines, or padding designed to spoof notification
/// text. Everything below `0x20` plus DEL and the Unicode line separators is
/// replaced by a space, then runs of whitespace collapse to one space.
pub fn sanitize_text(raw: &str) -> String {
    let mut out = String::with_capacity(raw.len());
    let mut pending_space = false;

    for ch in raw.chars() {
        let is_blank = ch.is_control()
            || ch.is_whitespace()
            || matches!(ch, '\u{2028}' | '\u{2029}' | '\u{feff}');

        if is_blank {
            pending_space = !out.is_empty();
            continue;
        }

        if pending_space {
            out.push(' ');
            pending_space = false;
        }
        out.push(ch);
    }

    out
}

/// Truncate on a character boundary, appending an ellipsis when shortened.
pub fn truncate_text(text: &str, max_len: usize) -> String {
    if text.chars().count() <= max_len {
        return text.to_string();
    }
    if max_len == 0 {
        return String::new();
    }

    // Reserve one character for the ellipsis.
    let keep = max_len.saturating_sub(1);
    let mut out: String = text.chars().take(keep).collect();
    while out.ends_with(' ') {
        out.pop();
    }
    out.push('\u{2026}');
    out
}

fn clean_field(value: Option<&str>) -> Option<String> {
    let cleaned = sanitize_text(value?);
    if cleaned.is_empty() {
        None
    } else {
        Some(cleaned)
    }
}

/// Render final notification text for a dispatch request.
///
/// Deliberately conservative: no shell output, no agent prompt text, and no
/// absolute paths. Native notifications can appear on a lock screen, so only
/// short display labels the user already chose are included.
pub fn format_notification(request: &DispatchNotificationRequest) -> NotificationContent {
    let agent = clean_field(request.agent_label.as_deref());
    let worktree = clean_field(request.worktree_label.as_deref());
    let workspace = clean_field(request.workspace_label.as_deref());
    let terminal = clean_field(request.terminal_title.as_deref());

    let (title, body) = match request.source {
        NotificationSource::AgentTaskComplete => {
            let title = match agent {
                Some(agent) => format!("{agent} finished"),
                None => "Agent finished".to_string(),
            };
            let body = worktree
                .or(workspace)
                .unwrap_or_else(|| "Task complete".to_string());
            (title, body)
        }
        NotificationSource::TerminalBell => {
            let title = "Terminal needs attention".to_string();
            let location = worktree.or(workspace);
            let body = match (location, terminal) {
                (Some(location), Some(terminal)) => format!("{location} \u{b7} {terminal}"),
                (Some(location), None) => location,
                (None, Some(terminal)) => terminal,
                (None, None) => "A terminal rang the bell".to_string(),
            };
            (title, body)
        }
        NotificationSource::Test => (
            "Ferryx notifications are working".to_string(),
            "Test notification".to_string(),
        ),
    };

    NotificationContent {
        title: truncate_text(&title, MAX_TITLE_LEN),
        body: truncate_text(&body, MAX_BODY_LEN),
    }
}

// ---------------------------------------------------------------------------
// Audio validation
// ---------------------------------------------------------------------------

/// Convert a frontend volume percentage to a linear gain.
///
/// Accepts `0..=100`; anything outside (including NaN) clamps into range so a
/// malformed setting can never produce a deafening or negative gain.
pub fn normalize_volume(percent: f32) -> f32 {
    if percent.is_nan() {
        return 0.0;
    }
    (percent / 100.0).clamp(0.0, 1.0)
}

/// True when the extension matches an enabled decoder.
pub fn is_supported_audio_extension(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .map(|ext| {
            let lower = ext.to_ascii_lowercase();
            SUPPORTED_AUDIO_EXTENSIONS.contains(&lower.as_str())
        })
        .unwrap_or(false)
}

/// Validate a custom sound path before any decoding is attempted.
///
/// Returns the canonicalized path so playback never follows a path that
/// changed between validation and open.
pub fn validate_audio_path(path: &Path) -> Result<PathBuf, PlaySoundReason> {
    if !is_supported_audio_extension(path) {
        return Err(PlaySoundReason::UnsupportedFormat);
    }

    let canonical = path.canonicalize().map_err(|_| PlaySoundReason::NotFound)?;

    let metadata = canonical
        .metadata()
        .map_err(|_| PlaySoundReason::NotFound)?;

    if !metadata.is_file() {
        return Err(PlaySoundReason::NotFound);
    }
    if metadata.len() > MAX_AUDIO_FILE_BYTES {
        return Err(PlaySoundReason::FileTooLarge);
    }

    Ok(canonical)
}

/// Display name for a picked file, falling back to the full path string.
pub fn audio_display_name(path: &Path) -> String {
    path.file_name()
        .and_then(|name| name.to_str())
        .map(|name| name.to_string())
        .unwrap_or_else(|| path.to_string_lossy().to_string())
}

//! Authoritative notification permission queries.

use super::model::{
    NotificationAuthorization, NotificationPermissionRequestDto, NotificationPermissionStatusDto,
    NotificationPlatform,
};

/// Seam over the OS permission backend.
pub trait NotificationPermissionProvider: Send + Sync {
    fn status(&self) -> NotificationPermissionStatusDto;
    fn request(&self) -> NotificationPermissionRequestDto;
}

/// Provider selected for the current build target.
pub fn platform_permission_provider() -> Box<dyn NotificationPermissionProvider> {
    #[cfg(target_os = "macos")]
    {
        Box::new(macos::MacosPermissionProvider)
    }
    #[cfg(not(target_os = "macos"))]
    {
        Box::new(DesktopFallbackPermissionProvider)
    }
}

/// Non-authoritative provider for platforms without a real permission query.
#[derive(Debug, Default, Clone, Copy)]
pub struct DesktopFallbackPermissionProvider;

impl NotificationPermissionProvider for DesktopFallbackPermissionProvider {
    fn status(&self) -> NotificationPermissionStatusDto {
        let platform = NotificationPlatform::current();
        let can_open_settings = matches!(platform, NotificationPlatform::Windows);
        NotificationPermissionStatusDto {
            platform,
            supported: true,
            authorization: NotificationAuthorization::Authorized,
            alerts_enabled: Some(true),
            sounds_enabled: Some(true),
            requested: true,
            authoritative: false,
            can_open_settings,
        }
    }

    fn request(&self) -> NotificationPermissionRequestDto {
        NotificationPermissionRequestDto {
            granted: true,
            status: self.status(),
            error: None,
        }
    }
}

#[cfg(target_os = "macos")]
pub mod macos {
    use super::*;
    use block2::RcBlock;
    use objc2_foundation::{NSBundle, NSError};
    use objc2_user_notifications::{
        UNAuthorizationOptions, UNAuthorizationStatus, UNNotificationSetting,
        UNNotificationSettings, UNUserNotificationCenter,
    };
    use std::ptr::NonNull;
    use std::sync::mpsc;
    use std::time::Duration;

    const CALLBACK_TIMEOUT: Duration = Duration::from_secs(5);

    pub fn map_authorization_status(status: UNAuthorizationStatus) -> NotificationAuthorization {
        match status {
            UNAuthorizationStatus::NotDetermined => NotificationAuthorization::NotDetermined,
            UNAuthorizationStatus::Denied => NotificationAuthorization::Denied,
            UNAuthorizationStatus::Authorized => NotificationAuthorization::Authorized,
            UNAuthorizationStatus::Provisional => NotificationAuthorization::Provisional,
            UNAuthorizationStatus::Ephemeral => NotificationAuthorization::Provisional,
            _ => NotificationAuthorization::Unknown,
        }
    }

    pub fn map_notification_setting(setting: UNNotificationSetting) -> Option<bool> {
        match setting {
            UNNotificationSetting::Enabled => Some(true),
            UNNotificationSetting::Disabled => Some(false),
            _ => None,
        }
    }

    pub fn has_bundle_identity() -> bool {
        // Only consider it a real bundled macOS app if the bundle identifier is present
        // AND the bundle path is actually inside a .app wrapper directory.
        if let Some(bundle_id) = NSBundle::mainBundle().bundleIdentifier() {
            if bundle_id.to_string().is_empty() {
                return false;
            }
            let path_str = NSBundle::mainBundle().bundlePath().to_string();
            return path_str.ends_with(".app") || path_str.contains(".app/");
        }
        false
    }

    pub fn dev_fallback_status() -> NotificationPermissionStatusDto {
        NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization: NotificationAuthorization::Authorized,
            alerts_enabled: Some(true),
            sounds_enabled: Some(true),
            requested: true,
            authoritative: false,
            can_open_settings: true,
        }
    }

    fn read_settings(settings: &UNNotificationSettings) -> NotificationPermissionStatusDto {
        let authorization = map_authorization_status(settings.authorizationStatus());
        NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization,
            alerts_enabled: map_notification_setting(settings.alertSetting()),
            sounds_enabled: map_notification_setting(settings.soundSetting()),
            requested: authorization != NotificationAuthorization::NotDetermined,
            authoritative: true,
            can_open_settings: true,
        }
    }

    fn query_settings() -> Option<NotificationPermissionStatusDto> {
        if !has_bundle_identity() {
            return None;
        }

        let (tx, rx) = mpsc::sync_channel::<NotificationPermissionStatusDto>(1);
        let handler = RcBlock::new(move |settings: NonNull<UNNotificationSettings>| {
            let status = read_settings(unsafe { settings.as_ref() });
            let _ = tx.try_send(status);
        });

        let dispatched = objc2::exception::catch(std::panic::AssertUnwindSafe(|| {
            let center = UNUserNotificationCenter::currentNotificationCenter();
            center.getNotificationSettingsWithCompletionHandler(&handler);
        }));

        if dispatched.is_err() {
            tracing::warn!("UNUserNotificationCenter settings query raised an exception");
            return None;
        }

        match rx.recv_timeout(CALLBACK_TIMEOUT) {
            Ok(status) => Some(status),
            Err(_) => {
                tracing::warn!("UNUserNotificationCenter settings query timed out");
                None
            }
        }
    }

    #[derive(Debug, Default, Clone, Copy)]
    pub struct MacosPermissionProvider;

    impl NotificationPermissionProvider for MacosPermissionProvider {
        fn status(&self) -> NotificationPermissionStatusDto {
            query_settings().unwrap_or_else(dev_fallback_status)
        }

        fn request(&self) -> NotificationPermissionRequestDto {
            if !has_bundle_identity() {
                // In dev mode / unbundled mode, grant immediately so dev testing works
                return NotificationPermissionRequestDto {
                    granted: true,
                    status: dev_fallback_status(),
                    error: None,
                };
            }

            let (tx, rx) = mpsc::sync_channel::<Result<bool, String>>(1);
            let handler = RcBlock::new(
                move |granted: objc2::runtime::Bool, error: *mut NSError| {
                    let outcome = if error.is_null() {
                        Ok(granted.as_bool())
                    } else {
                        Err(unsafe { (*error).localizedDescription() }.to_string())
                    };
                    let _ = tx.try_send(outcome);
                },
            );

            let options = UNAuthorizationOptions::Alert | UNAuthorizationOptions::Sound;
            let dispatched = objc2::exception::catch(std::panic::AssertUnwindSafe(|| {
                let center = UNUserNotificationCenter::currentNotificationCenter();
                center.requestAuthorizationWithOptions_completionHandler(options, &handler);
            }));

            if dispatched.is_err() {
                return NotificationPermissionRequestDto {
                    granted: false,
                    status: dev_fallback_status(),
                    error: Some("notification authorization request failed".into()),
                };
            }

            let (granted, error) = match rx.recv_timeout(CALLBACK_TIMEOUT) {
                Ok(Ok(granted)) => (granted, None),
                Ok(Err(message)) => (false, Some(message)),
                Err(_) => (false, Some("authorization request timed out".to_string())),
            };

            let status = query_settings().unwrap_or_else(dev_fallback_status);

            NotificationPermissionRequestDto {
                granted,
                status,
                error,
            }
        }
    }
}

//! Native notification domain.
//!
//! Rust decides *how* to talk to the OS safely; the frontend decides *whether*
//! an application event should notify. React state, active-tab knowledge, and
//! user-event dedupe deliberately stay out of this module.

pub mod audio;
pub mod model;
pub mod permission;
pub mod service;

pub use audio::*;
pub use model::*;
pub use permission::*;
pub use service::*;

/// Open the OS notification settings for rorca.
///
/// Deliberately narrow: the target is fixed per platform and never accepted
/// from the frontend, so this cannot become a general URI-open primitive.
pub fn open_system_notification_settings() -> OpenSystemSettingsResult {
    #[cfg(target_os = "macos")]
    {
        // On macOS, running `open x-apple.systempreferences:...` or opening System Settings
        // when the app is unbundled or unnotified causes unwanted disruptive UI popups.
        // Explicitly report unsupported to avoid unexpected System Settings window launches.
        OpenSystemSettingsResult {
            opened: false,
            reason: Some("opening system settings is disabled in dev/standalone mode".into()),
        }
    }

    #[cfg(target_os = "windows")]
    {
        if run_opener("cmd", &["/C", "start", "", "ms-settings:notifications"]) {
            return OpenSystemSettingsResult {
                opened: true,
                reason: None,
            };
        }
        OpenSystemSettingsResult {
            opened: false,
            reason: Some("could not open Windows notification settings".into()),
        }
    }

    // Linux desktop environments have no single notification settings target.
    #[cfg(not(any(target_os = "macos", target_os = "windows")))]
    {
        OpenSystemSettingsResult {
            opened: false,
            reason: Some("unsupported".into()),
        }
    }
}

#[cfg(any(target_os = "macos", target_os = "windows"))]
#[allow(dead_code)]
fn run_opener(program: &str, args: &[&str]) -> bool {
    std::process::Command::new(program)
        .args(args)
        .status()
        .map(|status| status.success())
        .unwrap_or(false)
}

